    facts: {
      de: ["Eines der ältesten Kraftwerke des Landes.", "Nutzt das Wasser des Kirirom-Plateaus."],
      hu: ["Az ország egyik legrégebbi erőműve.", "A Kirirom-fennsík vizét hasznosítja."],
      ro: ["Una dintre cele mai vechi centrale electrice din țară.", "Folosește apa de pe platoul Kirirom."],
      en: ["One of the country's oldest power plants.", "Utilizes water from the Kirirom Plateau."],
      es: ["Una de las centrales eléctricas más antiguas del país.", "Utiliza el agua de la meseta de Kirirom."],
      pt: ["Uma das usinas elétricas mais antigas do país.", "Utiliza a água do planalto de Kirirom."],
      fr: ["L'une des plus anciennes centrales électriques du pays.", "Utilise l'eau du plateau de Kirirom."],
    }, image: "/poi-images/kirirom-1-hydropower-economic-v2.webp",
    descriptionAdvanced: {
      de: "Das Wasserkraftwerk Kirirom 1 ist eine historische Energieanlage in der Provinz Kampong Speu, innerhalb des Kirirom-Nationalparks. Es wurde ursprünglich in den 1960er Jahren mit Hilfe jugoslawischer Entwicklungshilfe erbaut und war das erste Wasserkraftwerk des Landes. Während des kambodschanischen Bürgerkriegs wurde die Anlage schwer beschädigt und war jahrzehntelang außer Betrieb. Im Jahr 2002 wurde das Kraftwerk durch Investitionen der China Electric Power Technology and Equipment Association (CET) vollständig rekonstruiert und modernisiert. Heute verfügt Kirirom 1 über eine installierte Leistung von 12 Megawatt und dient als wichtiges Beispiel für den Wiederaufbau der nationalen Infrastruktur. Die Anlage nutzt das Wasser des Prek Thnot-Flusssystems in der bergigen Region des Elefantengebirges. Trotz seiner im Vergleich zu neueren Projekten geringen Größe bleibt es aufgrund seiner Pionierrolle und seiner Lage in einem Schutzgebiet von großer Bedeutung. Das Kraftwerk ist über eine Hochspannungsleitung mit dem Stromnetz von Phnom Penh verbunden.",
      hu: "A Kirirom 1 vízerőmű egy történelmi jelentőségű létesítmény Kampong Speu tartományban, a Kirirom Nemzeti Park területén. Eredetileg az 1960-as években épült jugoszláv segítséggel, és ez volt az ország legelső vízerőműve. A kambodzsai polgárháború alatt az erőmű súlyosan megsérült, és évtizedekig üzemen kívül állt. 2002-ben a létesítményt a China Electric Power Technology and Equipment Association (CET) beruházásában teljesen újjáépítették és modernizálták. Napjainkban a Kirirom 1 beépített teljesítménye 12 megawatt, és fontos példája a nemzeti infrastruktúra helyreállításának. Az erőmű az Elefánt-hegység hegyvidéki régiójában található Prek Thnot folyórendszer vizét hasznosítja. Annak ellenére, hogy mérete az újabb projektekhez képest csekély, úttörő szerepe és védett területen való elhelyezkedése miatt továbbra is nagy jelentőséggel bír. Az erőmű nagyfeszültségű vezetéken keresztül csatlakozik Phnom Penh elektromos hálózatához.",
      ro: "Centrala hidroelectrică Kirirom 1 este o facilitate energetică istorică situată în provincia Kampong Speu, în interiorul Parcului Național Kirirom. A fost construită inițial în anii 1960 cu asistență iugoslavă, fiind prima hidrocentrală din țară. În timpul războiului civil din Cambodgia, instalația a fost grav avariată și a rămas scoasă din funcțiune timp de decenii. În anul 2002, centrala a fost complet reconstruită și modernizată prin investiții ale asociației chineze CET (China Electric Power Technology and Equipment Association). Astăzi, Kirirom 1 are o capacitate instalată de 12 megawați și servește drept un exemplu important al reconstrucției infrastructurii naționale. Instalația utilizează resursele de apă ale sistemului hidrografic Prek Thnot din regiunea muntoasă a Munților Elefantului. Deși are o dimensiune redusă în comparație cu proiectele mai noi, rămâne extrem de semnificativă datorită rolului său de pionierat și locației sale într-o zonă protejată. Centrala furnizează energie rețelei din Phnom Penh printr-o linie de înaltă tensiune.",
      en: "The Kirirom 1 Hydropower Plant is a historical energy facility located in Kampong Speu Province, within the Kirirom National Park. It was originally built in the 1960s with Yugoslavian assistance and was the country's first hydroelectric power station. During the Cambodian Civil War, the plant was severely damaged and remained out of operation for decades. In 2002, the facility was completely reconstructed and modernized through investments by the China Electric Power Technology and Equipment Association (CET). Today, Kirirom 1 has an installed capacity of 12 megawatts and serves as an important example of national infrastructure restoration. The plant utilizes the water from the Prek Thnot river system in the mountainous region of the Elephant Mountains. Despite its small size compared to newer projects, it remains highly significant due to its pioneering role and its location within a protected area. The power station is connected to the Phnom Penh power grid via a high-voltage transmission line.",
      es: "La central hidroeléctrica Kirirom 1 se encuentra en el Parque Nacional Kirirom, en la provincia de Kampong Speu. Fue terminada en 2012 y tiene una potencia de 18 MW. La planta aprovecha el desnivel de la meseta de Kirirom e inyecta electricidad a la red nacional. El proyecto fue desarrollado por el gobierno camboyano con apoyo de Corea del Sur. El embalse tiene una superficie de 2 km². La central forma parte de un proyecto turístico, ya que el Parque Nacional Kirirom es un destino de excursión popular.",
      pt: "A usina hidrelétrica Kirirom 1 está localizada no Parque Nacional Kirirom, na província de Kampong Speu. Foi concluída em 2012 e tem uma potência de 18 MW. A instalação utiliza o declive do planalto de Kirirom e injeta eletricidade na rede nacional. O projeto foi desenvolvido pelo governo cambojano com o apoio da Coreia do Sul. O reservatório tem uma área de 2 km². A usina faz parte de um projeto turístico, uma vez que o Parque Nacional Kirirom é um destino popular para excursões.",
      fr: "La centrale hydroélectrique Kirirom 1 est située dans le parc national de Kirirom, dans la province de Kampong Speu. Elle a été achevée en 2012 et possède une puissance de 18 MW. L'installation utilise la pente du plateau de Kirirom et injecte de l'électricité dans le réseau national. Le projet a été développé par le gouvernement cambodgien avec le soutien de la Corée du Sud. Le réservoir a une superficie de 2 km². La centrale fait partie d'un projet touristique, le parc national de Kirirom étant une destination d'excursion prisée.",
    },
