      pt: ["A mina foi descoberta em 1963.", "O teor médio de ferro é de 56%.", "As reservas estão estimadas em 10,5 milhões de toneladas.", "A área de mineração é de 12,3 km².", "A profundidade das minas ativas é de até 150 metros.", "A produção anual em 2022 foi de 900.000 toneladas."],
      fr: ["La mine a été découverte en 1963.", "La teneur moyenne en fer est de 56 %.", "Les réserves sont estimées à 10,5 millions de tonnes.", "La surface d'exploitation est de 12,3 km².", "Profondeur des carrières actives jusqu'à 150 mètres.", "Production annuelle en 2022 de 900 000 tonnes."],
